// Generated by npm run build. Edit src/ files, then rebuild.
(() => {
'use strict';
const start = () => {
/** The document language uses indentation; expressions are kept as text, never executed. */
class ParseError extends Error {
  constructor(message, line) {
    super(message);
    this.name = 'ParseError';
    this.line = line;
  }
}

function parse(source) {
  if (source.length > 100_000) throw new ParseError('This document is too large (maximum 100,000 characters).', 1);
  const lines = source.replace(/\r\n?/g, '\n').split('\n').map((raw, i) => {
    const expanded = raw.replace(/^\t+/, tabs => '  '.repeat(tabs.length));
    const prefix = expanded.match(/^\s*/)[0];
    if (prefix.includes('\t')) throw new ParseError('Use spaces, or tabs alone, for indentation.', i + 1);
    return { text: expanded.trim(), indent: prefix.length, line: i + 1 };
  }).filter(line => line.text);
  if (!lines.length) throw new ParseError('Start with a routine signature, for example: algorithm(A : T[n])', 1);
  if (lines.length > 1500) throw new ParseError('Use at most 1,500 non-empty lines in a document.', 1);
  let index = 0;
  const fail = (message, token = lines[index]) => { throw new ParseError(message, token?.line ?? lines.at(-1).line); };
  const condition = (text, prefix, token) => {
    const value = text.slice(prefix.length).replace(/:\s*$/, '').trim();
    if (!value) fail('Add a condition after the control keyword.', token);
    return value;
  };
  function children(parent, depth) {
    if (depth > 24) fail('Use at most 24 nested blocks.', parent);
    if (!lines[index] || lines[index].indent <= parent.indent) fail('Indent a body below this line. Use SKIP for an empty branch.', parent);
    const body = sequence(lines[index].indent, depth);
    if (!body.length) fail('Add a statement here. A branch keyword needs its matching control block.');
    return body;
  }
  function selection(token, depth, labelPrefix = 'if ') {
    const label = condition(token.text, labelPrefix, token);
    const yes = children(token, depth + 1);
    let no = [{ type: 'statement', text: 'SKIP', line: token.line, implicit: true }];
    const next = lines[index];
    if (next && next.indent === token.indent && /^(else\s+if\s|elif\s)/.test(next.text)) {
      index++;
      no = [selection(next, depth + 1, next.text.startsWith('elif ') ? 'elif ' : 'else if ')];
    } else if (next && next.indent === token.indent && /^else:?$/.test(next.text)) {
      index++;
      no = children(next, depth + 1);
    }
    return { type: 'if', text: label, yes, no, line: token.line };
  }
  function sequence(indent, depth) {
    const nodes = [];
    while (index < lines.length && lines[index].indent >= indent) {
      const token = lines[index];
      if (token.indent !== indent) fail('Unexpected indentation. Align this line with the statements in its block.', token);
      if (/^(else\b|elif\b|case\b|otherwise\b)/.test(token.text)) break;
      index++;
      if (token.text.startsWith('if ')) nodes.push(selection(token, depth));
      else if (/^(while|for|foreach)\s/.test(token.text)) {
        const keyword = token.text.match(/^\w+\s+/)[0];
        let text = condition(token.text, keyword, token);
        if ((keyword.trim() === 'for' || keyword.trim() === 'foreach') && /\s(?:∈|in)\s/.test(text)) {
          text = '∀' + text.replace(/^∀/, '').replace(/\s+in\s+/, ' ∈ ');
        }
        nodes.push({ type: 'loop', text, body: children(token, depth + 1), line: token.line });
      } else if (/^select:?$/.test(token.text)) {
        if (!lines[index] || lines[index].indent <= indent) fail('Indent case branches below select.', token);
        const branchIndent = lines[index].indent;
        const branches = [];
        let hasDefault = false;
        while (lines[index]?.indent === branchIndent) {
          const branch = lines[index++];
          if (hasDefault) fail('The otherwise branch must come last.', branch);
          if (!/^case\s/.test(branch.text) && !/^otherwise:?$/.test(branch.text)) fail('Use case condition or otherwise inside select.', branch);
          hasDefault = /^otherwise/.test(branch.text);
          branches.push({ text: hasDefault ? 'otherwise' : condition(branch.text, 'case ', branch), line: branch.line, body: children(branch, depth + 1) });
          if (branches.length > 12) fail('Use at most 12 branches in a selection.', token);
        }
        if (branches.length < 2) fail('A selection needs at least two case branches.', token);
        nodes.push({ type: 'select', branches, line: token.line });
      } else {
        if (/^(if|while|for|foreach|else|elif|case|otherwise)\b/.test(token.text)) fail('Check the control keyword and its condition.', token);
        nodes.push({ type: 'statement', text: token.text, line: token.line });
      }
    }
    return nodes;
  }
  const routines = [];
  while (index < lines.length) {
    const token = lines[index++];
    if (token.indent !== 0) fail('Routine signatures start at the left edge, without indentation.', token);
    const signature = token.text.replace(/^(?:function|procedure)\s+/, '');
    if (!/^[\p{L}_][\p{L}\p{N}_:]*\s*\(.*\)/u.test(signature)) fail('Write a routine signature such as search(t : Node*; k : T) : Node*.', token);
    routines.push({ signature, body: children(token, 0), line: token.line });
    if (lines[index]?.indent > 0) fail('This branch has no matching control block. Align else with its if, and cases under select.');
  }
  return routines;
}

function notation(text) {
  if (text.startsWith('//')) return text;
  return text.replace(/->/g, '→').replace(/!=|<>/g, '≠').replace(/<=/g, '≤').replace(/>=/g, '≥')
    .replace(/&&/g, '∧').replace(/\|\|/g, '∨').replace(/!(?!=)/g, '¬').replace(/\b(?:NULL|null)\b/g, '∅');
}


function escapeXML(value) {
  return String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' })[character]);
}

/** All geometry is shared by the preview and exports. measure is a canvas text measurement in the browser. */
function render(routines, { measure = text => [...text].length * 10, title = 'Structogram' } = {}) {
  const padding = 24, rail = 24, lineHeight = 25;
  const wrapped = (text, maxWidth = 440) => {
    const result = [];
    let current = '';
    for (const word of notation(text).split(/(\s+)/)) {
      if (measure(current + word) <= maxWidth) { current += word; continue; }
      if (current.trim()) { result.push(current.trim()); current = ''; }
      for (const char of word) {
        if (measure(current + char) > maxWidth && current) { result.push(current.trim()); current = ''; }
        current += char;
      }
    }
    if (current.trim() || !result.length) result.push(current.trim());
    return result;
  };
  const label = text => {
    const lines = wrapped(text);
    return { lines, width: Math.max(82, ...lines.map(measure).map(width => Math.ceil(width) + padding)), height: Math.max(33, lines.length * lineHeight + 8) };
  };
  function sequence(nodes) {
    const items = nodes.map(layout);
    return { items, width: Math.max(82, ...items.map(item => item.width)), height: items.reduce((sum, item) => sum + item.height, 0) };
  }
  function layout(node) {
    if (node.type === 'statement') return { ...label(node.text), node };
    if (node.type === 'loop') {
      const header = label(node.text), body = sequence(node.body);
      return { node, header, body, width: Math.max(header.width, body.width + rail), height: header.height + body.height };
    }
    if (node.type === 'if') {
      const header = label(node.text), yes = sequence(node.yes), no = sequence(node.no);
      return { node, header, yes, no, width: Math.max(header.width + 18, yes.width + no.width), height: header.height + Math.max(yes.height, no.height) };
    }
    const branches = node.branches.map(branch => {
      const header = label(branch.text), body = sequence(branch.body);
      return { branch, header, body, width: Math.max(header.width + 18, body.width) };
    });
    const headerHeight = Math.max(...branches.map(branch => branch.header.height));
    return { node, branches, headerHeight, width: branches.reduce((sum, branch) => sum + branch.width, 0), height: headerHeight + Math.max(...branches.map(branch => branch.body.height)) };
  }
  const documents = routines.map(routine => {
    const body = sequence(routine.body), signature = label(routine.signature);
    return { routine, body, signature, width: Math.max(280, body.width, signature.width), height: signature.height + 12 + body.height };
  });
  const width = Math.max(...documents.map(document => document.width)) + 60;
  const height = documents.reduce((sum, document) => sum + document.height, 0) + 60 + (documents.length - 1) * 40;
  const parts = [`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="diagram-title diagram-description"><title id="diagram-title">${escapeXML(title)}</title><desc id="diagram-description">Course-style structure diagram. ${routines.length} routine${routines.length === 1 ? '' : 's'}. Use the source editor for an accessible text version.</desc><style>text{font-family:"Times New Roman",Georgia,serif;font-size:18px;fill:#20251f} .rule{fill:none;stroke:#363c34;stroke-width:.85;stroke-linejoin:miter}.hit-area{fill:#fff;fill-opacity:0} .comment{fill:#858b80}</style><rect width="100%" height="100%" fill="white"/>`];
  const rect = (x, y, w, h, radius = 0) => parts.push(`<rect class="rule" x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}"/>`);
  const line = (x1, y1, x2, y2) => parts.push(`<path class="rule" d="M${x1} ${y1}L${x2} ${y2}"/>`);
  const hit = (sourceLine, x, y, w, h) => parts.push(`<g data-line="${sourceLine}"><rect class="hit-area" x="${x}" y="${y}" width="${w}" height="${h}"/>`);
  const text = (lines, x, y, w, h, { signature = false, comment = false } = {}) => {
    const start = y + h / 2 - (lines.length - 1) * lineHeight / 2;
    lines.forEach((value, i) => {
      const isSkip = value === 'SKIP';
      const content = /^return\b/.test(value)
        ? `<tspan font-weight="bold" font-style="normal">return</tspan>${escapeXML(value.slice(6))}`
        : escapeXML(value);
      parts.push(`<text x="${x + w / 2}" y="${start + i * lineHeight}" text-anchor="middle" dominant-baseline="central" font-style="${signature || isSkip ? 'normal' : 'italic'}"${comment ? ' class="comment"' : ''}>${content}</text>`);
    });
  };
  const diagonal = (x, y, w, h) => { line(x, y + h - 19, x + 8, y + h); line(x + w, y + h - 19, x + w - 8, y + h); };
  function drawSequence(seq, x, y, w, h = seq.height) {
    let position = y;
    seq.items.forEach((item, i) => {
      // Stretch the last row to fill a shorter selection branch, keeping all branches closed.
      const itemHeight = item.height + (i === seq.items.length - 1 ? h - seq.height : 0);
      draw(item, x, position, w, itemHeight);
      position += itemHeight;
    });
  }
  function draw(item, x, y, w, h) {
    const { node } = item;
    if (node.type === 'statement') {
      hit(node.line, x, y, w, h);
      rect(x, y, w, h);
      text(item.lines, x, y, w, h, { comment: node.text.startsWith('//') });
      parts.push('</g>');
    } else if (node.type === 'loop') {
      rect(x, y, w, h);
      hit(node.line, x, y, w, item.header.height);
      text(item.header.lines, x, y, w, item.header.height);
      line(x + rail, y + item.header.height, x + w, y + item.header.height);
      parts.push('</g>');
      drawSequence(item.body, x + rail, y + item.header.height, w - rail, h - item.header.height);
    } else if (node.type === 'if') {
      const headerH = item.header.height;
      hit(node.line, x, y, w, headerH);
      rect(x, y, w, headerH);
      diagonal(x, y, w, headerH);
      text(item.header.lines, x, y, w, headerH);
      parts.push('</g>');
      const split = Math.round(w * item.yes.width / (item.yes.width + item.no.width));
      drawSequence(item.yes, x, y + headerH, split, h - headerH);
      drawSequence(item.no, x + split, y + headerH, w - split, h - headerH);
    } else {
      let position = x;
      item.branches.forEach((branch, i) => {
        const branchW = i === item.branches.length - 1 ? x + w - position : Math.round(w * branch.width / item.width);
        hit(branch.branch.line, position, y, branchW, item.headerHeight);
        rect(position, y, branchW, item.headerHeight);
        diagonal(position, y, branchW, item.headerHeight);
        text(branch.header.lines, position, y, branchW, item.headerHeight);
        parts.push('</g>');
        drawSequence(branch.body, position, y + item.headerHeight, branchW, h - item.headerHeight);
        position += branchW;
      });
    }
  }
  let position = 30;
  for (const { routine, signature, body, width: documentWidth, height: documentHeight } of documents) {
    const x = (width - documentWidth) / 2, signatureWidth = Math.min(documentWidth, signature.width);
    hit(routine.line, (width - signatureWidth) / 2, position, signatureWidth, signature.height);
    rect((width - signatureWidth) / 2, position, signatureWidth, signature.height, 13);
    text(signature.lines, 0, position, width, signature.height, { signature: true });
    parts.push('</g>');
    drawSequence(body, x, position + signature.height + 12, documentWidth);
    position += documentHeight + 40;
  }
  parts.push('</svg>');
  return { svg: parts.join(''), width, height };
}

const examples = [
  {
    id: 'insertion', title: 'Insertion sort', description: 'ADS I · p. 20',
    source: `insertionSort(A : T[n])
  for i := 1 to n − 1
    if A[i−1] > A[i]
      x := A[i]
      A[i] := A[i−1]
      j := i − 2
      while j ≥ 0 ∧ A[j] > x
        A[j+1] := A[j]
        j := j − 1
      A[j+1] := x
    else
      SKIP`
  },
  {
    id: 'search', title: 'BST search', description: 'ADS I · p. 54',
    source: `search(t : Node*; k : T) : Node*
  while t ≠ ∅ ∧ t→key ≠ k
    if k < t→key
      t := t→left
    else
      t := t→right
  return t`
  },
  {
    id: 'traversal', title: 'Tree traversals', description: 'ADS I · binary trees',
    source: `preorder(t : Node*)
  if t ≠ ∅
    process(t)
    preorder(t→left)
    preorder(t→right)

inorder(t : Node*)
  if t ≠ ∅
    inorder(t→left)
    process(t)
    inorder(t→right)

postorder(t : Node*)
  if t ≠ ∅
    postorder(t→left)
    postorder(t→right)
    process(t)`
  },
  {
    id: 'insert', title: 'BST insertion', description: 'ADS I · p. 54',
    source: `insert(&t : Node*; k : T)
  if t = ∅
    t := new Node(k)
  else
    select
      case k < t→key
        insert(t→left, k)
      case k > t→key
        insert(t→right, k)
      case k = t→key
        SKIP`
  },
  {
    id: 'bfs', title: 'Breadth-first search', description: 'ADS II · Graphs, p. 15',
    source: `BFS(G : G; s : V)
  for u ∈ G.V
    d(u) := ∞; π(u) := ∅
  d(s) := 0
  Q : Queue; Q.add(s)
  while ¬Q.isEmpty()
    u := Q.rem()
    for v ∈ G.A(u)
      if d(v) = ∞
        d(v) := d(u) + 1
        π(v) := u
        Q.add(v)
      else
        SKIP`
  },
  {
    id: 'balances', title: 'Fill AVL balances', description: 'ADS II · practice AVL-7, worked example',
    source: `fillBalances(t : Node*) : Z
  if t = ∅
    return −1
  else
    leftHeight := fillBalances(t→left)
    rightHeight := fillBalances(t→right)
    t→b := rightHeight − leftHeight
    return 1 + max(leftHeight, rightHeight)`
  }
];

const blank = { title: 'Untitled algorithm', source: 'algorithm(A : T[n])\n  SKIP' };


/** Convert our course AST to Blockly's data format. No expression is executed. */
function sourceToBlocks(source) {
  const original = source.split(/\r?\n/);
  function chain(nodes) {
    let next;
    for (const node of [...nodes].reverse()) {
      let block;
      if (node.type === 'statement') block = { type: 'ads_statement', fields: { TEXT: node.text } };
      else if (node.type === 'loop') {
        const isFor = /^\s*(for|foreach)\s/.test(original[node.line - 1]);
        block = { type: isFor ? 'ads_for' : 'ads_while', fields: { CONDITION: node.text }, inputs: { BODY: { block: chain(node.body) } } };
      } else if (node.type === 'if') {
        block = { type: 'ads_if', fields: { CONDITION: node.text }, inputs: { YES: { block: chain(node.yes) }, NO: { block: chain(node.no) } } };
      } else {
        const cases = node.branches.map(branch => ({
          type: 'ads_case', data: String(branch.line), fields: { CONDITION: branch.text }, inputs: { BODY: { block: chain(branch.body) } }
        }));
        block = { type: 'ads_select', inputs: { BRANCHES: { block: link(cases) } } };
      }
      block.data = String(node.line);
      if (next) block.next = { block: next };
      next = block;
    }
    return next;
  }
  function link(blocks) {
    let next;
    for (const block of [...blocks].reverse()) { if (next) block.next = { block: next }; next = block; }
    return next;
  }
  return { blocks: { languageVersion: 0, blocks: parse(source).map((routine, index) => ({
    type: 'ads_routine', data: String(routine.line), x: 35, y: 35 + index * 300,
    fields: { SIGNATURE: routine.signature }, inputs: { BODY: { block: chain(routine.body) } }
  })) } };
}

/** Generate the editable pseudocode, keeping a map from diagram rows to blocks. */
function blocksToSource(state) {
  const lines = [], lineMap = {};
  let count = 0;
  function field(block, name, fallback) {
    const value = String(block.fields?.[name] ?? fallback).trim();
    if (/[\r\n]/.test(value)) throw new Error('Write one statement or condition per block.');
    return value || fallback;
  }
  function emit(text, depth, block) {
    lines.push('  '.repeat(depth) + text);
    if (block.id) lineMap[lines.length] = block.id;
  }
  function body(block, name, depth) {
    const child = block.inputs?.[name]?.block;
    if (child) sequence(child, depth);
    else emit('SKIP', depth, block);
  }
  function sequence(first, depth) {
    if (depth > 25) throw new Error('Use at most 24 nested blocks.');
    for (let block = first; block; block = block.next?.block) {
      if (++count > 1500) throw new Error('Use at most 1,500 blocks.');
      switch (block.type) {
        case 'ads_statement': emit(field(block, 'TEXT', 'SKIP'), depth, block); break;
        case 'ads_for': case 'ads_while':
          emit((block.type === 'ads_for' ? 'for ' : 'while ') + field(block, 'CONDITION', block.type === 'ads_for' ? 'i := 0 to n − 1' : 'condition'), depth, block);
          body(block, 'BODY', depth + 1); break;
        case 'ads_if':
          emit('if ' + field(block, 'CONDITION', 'condition'), depth, block);
          body(block, 'YES', depth + 1);
          emit('else', depth, block);
          body(block, 'NO', depth + 1); break;
        case 'ads_select': {
          emit('select', depth, block);
          let branch = block.inputs?.BRANCHES?.block, branches = 0;
          while (branch) {
            if (branch.type !== 'ads_case') throw new Error('Only case blocks belong inside a selection.');
            if (++branches > 12) throw new Error('Use at most 12 case branches.');
            const condition = field(branch, 'CONDITION', 'condition');
            emit(condition === 'otherwise' ? 'otherwise' : 'case ' + condition, depth + 1, branch);
            body(branch, 'BODY', depth + 2);
            branch = branch.next?.block;
          }
          if (branches < 2) throw new Error('Add at least two case blocks inside the selection.');
          break;
        }
        default: throw new Error('Place case blocks inside a selection, and other blocks inside an algorithm.');
      }
    }
  }
  const top = state.blocks?.blocks ?? [];
  if (!top.length) throw new Error('Add an Algorithm block to begin.');
  for (const [index, routine] of top.entries()) {
    if (routine.type !== 'ads_routine') throw new Error('Connect loose blocks inside an Algorithm block.');
    if (index) lines.push('');
    emit(field(routine, 'SIGNATURE', 'algorithm()'), 0, routine);
    body(routine, 'BODY', 1);
    if (routine.next?.block) throw new Error('Algorithms must be separate top-level blocks.');
  }
  return { source: lines.join('\n'), lineMap };
}


function defineAdsBlocks(B) {
  const textField = value => new B.FieldTextInput(value, value => value.replace(/[\r\n]/g, ' '));
  function statement(block, color) { block.setPreviousStatement(true, 'ADS'); block.setNextStatement(true, 'ADS'); block.setColour(color); }
  B.Blocks.ads_routine = { init() {
    this.appendDummyInput().appendField('algorithm').appendField(textField('algorithm()'), 'SIGNATURE');
    this.appendStatementInput('BODY').setCheck('ADS').appendField('do');
    this.setColour('#315c62'); this.setTooltip('Name the algorithm and place its statements inside.');
  } };
  B.Blocks.ads_statement = { init() {
    this.appendDummyInput().appendField('statement').appendField(textField('SKIP'), 'TEXT');
    statement(this, '#40755a'); this.setTooltip('Write an assignment, declaration, call, return, or SKIP.');
  } };
  B.Blocks.ads_if = { init() {
    this.appendDummyInput().appendField('if').appendField(textField('condition'), 'CONDITION');
    this.appendStatementInput('YES').setCheck('ADS').appendField('then');
    this.appendStatementInput('NO').setCheck('ADS').appendField('else');
    statement(this, '#9c7135'); this.setTooltip('Edit the condition; place statements in the then and else branches.');
  } };
  for (const [type, label, placeholder] of [['ads_while', 'while', 'condition'], ['ads_for', 'for', 'i := 0 to n − 1']]) {
    B.Blocks[type] = { init() {
      this.appendDummyInput().appendField(label).appendField(textField(placeholder), 'CONDITION');
      this.appendStatementInput('BODY').setCheck('ADS').appendField('do');
      statement(this, '#3c7d79'); this.setTooltip('Edit the loop condition or range, then add statements inside.');
    } };
  }
  B.Blocks.ads_select = { init() {
    this.appendDummyInput().appendField('selection');
    this.appendStatementInput('BRANCHES').setCheck('CASE').appendField('cases');
    statement(this, '#9c7135'); this.setTooltip('Place two or more case blocks here; use otherwise for a final default branch.');
  } };
  B.Blocks.ads_case = { init() {
    this.appendDummyInput().appendField('case').appendField(textField('condition'), 'CONDITION');
    this.appendStatementInput('BODY').setCheck('ADS').appendField('do');
    this.setPreviousStatement(true, 'CASE'); this.setNextStatement(true, 'CASE'); this.setColour('#ac8450');
    this.setTooltip('A branch of a selection. Write otherwise for the final default branch.');
  } };
}

function createBlockEditor(element, onChange) {
  const B = window.Blockly;
  if (!B) throw new Error('The block editor could not load. Reopen the page online to reload its files.');
  defineAdsBlocks(B);
  const toolbox = { kind: 'categoryToolbox', contents: [
    { kind: 'category', name: 'Algorithm', colour: '#315c62', contents: [{ kind: 'block', type: 'ads_routine' }] },
    { kind: 'category', name: 'Statements', colour: '#40755a', contents: [{ kind: 'block', type: 'ads_statement' }] },
    { kind: 'category', name: 'Conditions', colour: '#9c7135', contents: [{ kind: 'block', type: 'ads_if' }, { kind: 'block', type: 'ads_select', inputs: { BRANCHES: { block: { type: 'ads_case', fields: { CONDITION: 'condition' }, next: { block: { type: 'ads_case', fields: { CONDITION: 'otherwise' } } } } } } }, { kind: 'block', type: 'ads_case' }] },
    { kind: 'category', name: 'Loops', colour: '#3c7d79', contents: [{ kind: 'block', type: 'ads_while' }, { kind: 'block', type: 'ads_for' }] }
  ] };
  const workspace = B.inject(element, {
    toolbox, renderer: 'zelos', media: './vendor/blockly/media/', sounds: false,
    trashcan: true, scrollbars: true, move: { scrollbars: true, drag: true, wheel: true },
    zoom: { controls: true, wheel: false, startScale: .85, minScale: .3, maxScale: 1.6 },
    grid: { spacing: 20, length: 2, colour: '#e2e8dd', snap: true }
  });
  let suspended = false, lineMap = {}, lastSource = '', lastError = null, timer;
  function save() { return B.serialization.workspaces.save(workspace); }
  function publish() {
    clearTimeout(timer);
    if (suspended) return;
    try {
      const generated = blocksToSource(save());
      const changed = generated.source !== lastSource || lastError !== null;
      if (changed) {
        lineMap = generated.lineMap;
        const seen = new Set();
        for (const [line, id] of Object.entries(lineMap)) {
          if (!seen.has(id)) { workspace.getBlockById(id).data = line; seen.add(id); }
        }
      }
      lastSource = generated.source; lastError = null;
      onChange({ source: generated.source, state: save(), changed });
    } catch (error) { lastError = error; onChange({ error, state: save() }); }
  }
  workspace.addChangeListener(event => {
    if (!event.isUiEvent && !suspended && event.type !== B.Events.FINISHED_LOADING) {
      clearTimeout(timer); timer = setTimeout(publish, 80);
    }
  });
  return {
    workspace,
    get error() { return lastError; },
    load(source, savedState) {
      const state = savedState || sourceToBlocks(source);
      suspended = true; clearTimeout(timer); B.Events.disable();
      try {
        workspace.clear();
        B.serialization.workspaces.load(state, workspace);
        if (!savedState) workspace.cleanUp();
        workspace.clearUndo();
        lineMap = {};
        for (const block of workspace.getAllBlocks(false)) if (block.data && !lineMap[Number(block.data)]) lineMap[Number(block.data)] = block.id;
        try { lastSource = blocksToSource(save()).source; lastError = null; }
        catch (error) { lastError = error; lastSource = ''; }
      } finally { B.Events.enable(); suspended = false; }
      if (lastError) onChange({ error: lastError, state: save() });
    },
    save,
    flush: publish,
    resize() { B.svgResize(workspace); },
    undo(redo = false) { workspace.undo(redo); publish(); },
    selectLine(line) { const block = workspace.getBlockById(lineMap[line]); if (block) { B.getFocusManager().focusNode(block); block.select(); workspace.centerOnBlock(block.id); } },
    insertSymbol(symbol) {
      const active = document.activeElement;
      if (active?.classList.contains('blocklyHtmlInput')) {
        active.setRangeText(symbol, active.selectionStart, active.selectionEnd, 'end');
        active.dispatchEvent(new Event('input', { bubbles: true })); return true;
      }
      const block = B.getSelected();
      const field = block?.getField('TEXT') || block?.getField('CONDITION') || block?.getField('SIGNATURE');
      if (!field) return false;
      field.setValue(field.getValue() + symbol); return true;
    }
  };
}

function initWorkspaceLayout(onResize) {
  const workspace = document.querySelector('.editor-workspace');
  const divider = document.getElementById('panel-divider');
  const panels = { algorithm: document.getElementById('algorithm-panel'), structogram: document.getElementById('structogram-panel') };
  const buttons = Object.fromEntries(Object.keys(panels).map(name => [name, document.getElementById('expand-' + name)]));
  const key = 'structogram.ads.layout.v1';
  const desktopLayout = matchMedia('(min-width: 861px)');
  let ratio = 44, expanded = null, dragging = null;
  try {
    const saved = JSON.parse(localStorage.getItem(key));
    if (typeof saved?.ratio === 'number' && Number.isFinite(saved.ratio)) ratio = Math.max(20, Math.min(80, saved.ratio));
  } catch { /* Layout remains usable when storage is unavailable. */ }
  function bounds() {
    const available = Math.max(1, workspace.clientWidth - divider.offsetWidth);
    const min = Math.max(20, Math.min(45, 280 / available * 100));
    return [min, 100 - min];
  }
  function apply() {
    if (desktopLayout.matches && !expanded) {
      const [min, max] = bounds();
      const displayed = Math.max(min, Math.min(max, ratio));
      workspace.style.setProperty('--algorithm-share', displayed + 'fr');
      workspace.style.setProperty('--structogram-share', (100 - displayed) + 'fr');
      divider.setAttribute('aria-valuemin', Math.ceil(min));
      divider.setAttribute('aria-valuemax', Math.floor(max));
      divider.setAttribute('aria-valuenow', Math.round(displayed));
      divider.setAttribute('aria-valuetext', `Algorithm ${Math.round(displayed)}%, structogram ${Math.round(100 - displayed)}%`);
    }
    onResize();
  }
  function save() { try { localStorage.setItem(key, JSON.stringify({ ratio })); } catch { /* Optional preference. */ } }
  function change(value) {
    const [min, max] = bounds();
    ratio = Math.max(min, Math.min(max, value));
    apply();
  }
  function endDrag() {
    if (dragging === null) return;
    const pointer = dragging;
    dragging = null;
    if (divider.hasPointerCapture(pointer)) divider.releasePointerCapture(pointer);
    document.body.classList.remove('resizing-panels');
    save();
  }
  divider.addEventListener('pointerdown', event => {
    if (event.button !== 0 || expanded || !desktopLayout.matches) return;
    event.preventDefault();
    divider.focus();
    dragging = event.pointerId;
    divider.setPointerCapture(dragging);
    document.body.classList.add('resizing-panels');
  });
  divider.addEventListener('pointermove', event => {
    if (event.pointerId !== dragging) return;
    const rect = workspace.getBoundingClientRect();
    change((event.clientX - rect.left - workspace.clientLeft - divider.offsetWidth / 2) / (workspace.clientWidth - divider.offsetWidth) * 100);
  });
  for (const name of ['pointerup', 'pointercancel', 'lostpointercapture']) divider.addEventListener(name, endDrag);
  window.addEventListener('blur', endDrag);
  divider.addEventListener('dblclick', () => { ratio = 44; apply(); save(); });
  divider.addEventListener('keydown', event => {
    const [min, max] = bounds(), current = Number(divider.getAttribute('aria-valuenow'));
    const step = event.shiftKey ? 10 : 2;
    const next = { ArrowLeft: current - step, ArrowRight: current + step, Home: min, End: max, Enter: 44 }[event.key];
    if (next === undefined) return;
    event.preventDefault(); change(next); save();
  });
  function expand(name) {
    endDrag();
    expanded = expanded === name ? null : name;
    workspace.dataset.expanded = expanded || '';
    document.body.classList.toggle('panel-expanded', Boolean(expanded));
    for (const [id, button] of Object.entries(buttons)) {
      const active = id === expanded;
      button.setAttribute('aria-pressed', String(active));
      button.setAttribute('aria-label', active ? 'Restore split view' : `Expand ${id} panel`);
      button.title = active ? 'Restore split view (Esc)' : `Expand ${id} panel`;
      button.textContent = active ? '↙ Restore' : '⛶';
    }
    // Keep focus in the visible panel; collapsing returns it to the same control.
    buttons[name].focus({ preventScroll: true });
    requestAnimationFrame(apply);
  }
  for (const name of Object.keys(panels)) buttons[name].addEventListener('click', () => expand(name));
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && expanded && !event.defaultPrevented && !document.querySelector('dialog[open]')) {
      event.preventDefault(); expand(expanded);
    }
  });
  new ResizeObserver(apply).observe(workspace);
  desktopLayout.addEventListener('change', () => { endDrag(); apply(); });
  apply();
}


const $ = id => document.getElementById(id);
const source = $('source'), stage = $('diagram-stage'), title = $('document-title');
const storageKey = 'structogram.ads.workspace.v1';
const canvas = document.createElement('canvas');
const context = canvas.getContext('2d');
context.font = 'italic 18px "Times New Roman", Georgia, serif';
let documentState = { ...examples[0], modified: false };
let currentDiagram, valid = false, zoom = 1, fitMode = true, renderTimer, toastTimer, pendingReplacement;
let storageAvailable = true;
// Start in text mode so restoring a saved text document never flushes an empty workspace.
let visual = null, editorMode = 'text', lastBlockSource = '';

try {
  const stored = JSON.parse(localStorage.getItem(storageKey));
  if (stored && typeof stored.source === 'string' && typeof stored.title === 'string' && stored.source.length <= 100_000) {
    documentState = { ...stored, title: stored.title.slice(0, 100) };
  }
} catch { storageAvailable = false; }

function toast(message) {
  clearTimeout(toastTimer);
  $('toast').textContent = message;
  $('toast').hidden = false;
  toastTimer = setTimeout(() => { $('toast').hidden = true; }, 3500);
}

function persist() {
  documentState.source = source.value;
  documentState.title = title.value;
  documentState.editorMode = editorMode;
  try {
    localStorage.setItem(storageKey, JSON.stringify(documentState));
    storageAvailable = true;
    $('save-status').textContent = 'Saved on this device';
  } catch {
    storageAvailable = false;
    $('save-status').textContent = 'Use Save source to keep your work';
  }
}

function updateDocumentLabel() {
  $('document-label').textContent = title.value.trim() || 'Untitled algorithm';
  document.title = `${title.value.trim() || 'Untitled algorithm'} — Structogram`;
  for (const button of $('examples').children) {
    const active = button.dataset.example === documentState.id;
    button.classList.toggle('is-active', active);
    if (active) button.setAttribute('aria-current', 'true');
    else button.removeAttribute('aria-current');
  }
}

function updateLines() {
  $('line-numbers').textContent = source.value.split('\n').map((_, i) => i + 1).join('\n');
  $('line-numbers').scrollTop = source.scrollTop;
  updateCursor();
}

function updateCursor() {
  if (editorMode === 'blocks') { $('cursor-position').textContent = 'Visual editing'; return; }
  const before = source.value.slice(0, source.selectionStart).split('\n');
  $('cursor-position').textContent = `Ln ${before.length}, Col ${before.at(-1).length + 1}`;
}

function exportEnabled(enabled) {
  $('export-diagram').disabled = !enabled;
  $('print-diagram').disabled = !enabled;
}

function applyZoom() {
  if (!currentDiagram) return;
  if (fitMode) {
    const viewport = $('preview-viewport');
    const style = getComputedStyle(viewport);
    const available = viewport.clientWidth - parseFloat(style.paddingLeft) - parseFloat(style.paddingRight);
    zoom = Math.min(1, Math.max(.08, available / currentDiagram.width));
  }
  stage.style.width = `${currentDiagram.width * zoom}px`;
  stage.style.height = `${currentDiagram.height * zoom}px`;
  $('zoom-reset').textContent = `${Math.round(zoom * 100)}%`;
  $('zoom-fit').setAttribute('aria-pressed', String(fitMode));
}

function updatePreview() {
  clearTimeout(renderTimer);
  try {
    if (editorMode === 'blocks' && visual?.error) throw visual.error;
    const routines = parse(source.value);
    currentDiagram = render(routines, { measure: text => context.measureText(text).width, title: title.value.trim() || 'Structogram' });
    stage.innerHTML = currentDiagram.svg;
    stage.classList.remove('is-stale');
    $('parse-error').hidden = true;
    $('diagram-status').textContent = '';
    const dot = document.createElement('span');
    dot.className = 'status-dot';
    $('diagram-status').append(dot, document.createTextNode(`Diagram is up to date${routines.length > 1 ? ` · ${routines.length} routines` : ''}`));
    valid = true;
    exportEnabled(true);
    applyZoom();
  } catch (error) {
    valid = false;
    stage.classList.add('is-stale');
    $('parse-error').textContent = `${error.line ? `Line ${error.line}` : 'Blocks'}: ${error.message}`;
    $('parse-error').hidden = false;
    $('diagram-status').textContent = 'Preview paused · fix the highlighted issue';
    exportEnabled(false);
  }
}

function documentChanged(fromBlocks = false) {
  documentState.modified = true;
  documentState.id = null;
  if (fromBlocks !== true) {
    lastBlockSource = '';
    delete documentState.blockWorkspace;
    delete documentState.blockSource;
  }
  updateLines();
  persist();
  updateDocumentLabel();
  valid = false;
  exportEnabled(false);
  $('diagram-status').textContent = 'Updating preview…';
  clearTimeout(renderTimer);
  renderTimer = setTimeout(updatePreview, 160);
}

function loadDocument(next) {
  documentState = { title: next.title, source: next.source, id: next.id || null, modified: false };
  source.value = next.source;
  title.value = next.title;
  source.scrollTop = source.scrollLeft = 0;
  fitMode = true;
  lastBlockSource = '';
  if (editorMode === 'blocks' && visual) {
    try { visual.load(next.source); lastBlockSource = next.source; }
    catch { editorMode = 'text'; setEditorMode('text'); }
  }
  persist();
  updateLines();
  updateDocumentLabel();
  updatePreview();
}

function setEditorMode(mode) {
  if (mode === 'blocks') {
    if (!visual) { toast('The visual editor is unavailable. Reopen the page online to reload its files.'); return false; }
    try {
      parse(source.value);
      if (lastBlockSource !== source.value) {
        visual.load(source.value, documentState.blockSource === source.value ? documentState.blockWorkspace : null);
        lastBlockSource = source.value;
      }
    } catch (error) { toast(`Fix the text first: ${error.message}`); return false; }
  } else if (editorMode === 'blocks' && visual) {
    visual.flush();
    if (visual.error) { toast(visual.error.message); return false; }
  }
  editorMode = mode;
  $('blocks-panel').hidden = mode !== 'blocks';
  $('text-panel').hidden = mode !== 'text';
  for (const name of ['blocks', 'text']) {
    $('mode-' + name).setAttribute('aria-selected', String(name === mode));
    $('mode-' + name).tabIndex = name === mode ? 0 : -1;
  }
  $('editor-hint').textContent = mode === 'blocks' ? 'Click a diagram row to find its block' : 'Tab to indent · click a diagram row to edit';
  updateCursor();
  if (mode === 'blocks') requestAnimationFrame(() => visual.resize());
  persist();
  updatePreview();
  return true;
}

function undoEditing(redo = false) {
  if (document.activeElement?.classList.contains('blocklyHtmlInput')) document.execCommand(redo ? 'redo' : 'undo');
  else if (editorMode === 'blocks') visual?.undo(redo);
  else { source.focus(); document.execCommand(redo ? 'redo' : 'undo'); }
}

function replaceDocument(next) {
  closeNavigation();
  if (documentState.modified && (source.value !== next.source || title.value !== next.title)) {
    pendingReplacement = next;
    $('replace-dialog').showModal();
  } else loadDocument(next);
}

function closeNavigation() {
  document.body.classList.remove('nav-open');
  $('nav-backdrop').hidden = true;
  $('toggle-nav').setAttribute('aria-expanded', 'false');
}

function editText(start, end, text) {
  source.focus();
  source.setSelectionRange(start, end);
  // insertText preserves the native undo history; setRangeText is the fallback.
  if (!document.execCommand('insertText', false, text)) {
    source.setRangeText(text, start, end, 'end');
    documentChanged();
  }
  updateCursor();
}

const snippets = {
  statement: 'statement',
  if: 'if condition\n  SKIP\nelse\n  SKIP',
  while: 'while condition\n  SKIP',
  for: 'for i := 0 to n − 1\n  SKIP',
  select: 'select\n  case condition\n    SKIP\n  otherwise\n    SKIP'
};

function insertConstruct(kind) {
  const position = source.selectionStart;
  const lineStart = source.value.lastIndexOf('\n', position - 1) + 1;
  const lineEnd = source.value.indexOf('\n', position);
  const end = lineEnd === -1 ? source.value.length : lineEnd;
  const currentLine = source.value.slice(lineStart, end);
  const indent = currentLine.match(/^\s*/)[0] || '  ';
  const snippet = snippets[kind].split('\n').map(line => indent + line).join('\n');
  if (!currentLine.trim() || currentLine.trim() === 'SKIP') {
    editText(lineStart, end, snippet);
    source.setSelectionRange(lineStart + indent.length, lineStart + snippet.length);
  } else {
    editText(end, end, '\n' + snippet);
    source.setSelectionRange(end + 1 + indent.length, end + 1 + snippet.length);
  }
  updateCursor();
}

async function download(blob, extension) {
  const filename = (title.value.trim().replace(/[^\p{L}\p{N}_.-]+/gu, '-').replace(/^-+|-+$/g, '') || 'algorithm') + extension;
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 30_000);
  return true;
}

async function saveSource() {
  if (editorMode === 'blocks') {
    visual?.flush();
    if (visual?.error) { toast('Connect or remove loose blocks before saving source.'); return; }
  }
  try {
    if (await download(new Blob([source.value], { type: 'text/plain;charset=utf-8' }), '.ads')) toast('Source file saved');
  } catch { toast('Could not save the file. Try another location.'); }
}

async function exportDiagram() {
  if (editorMode === 'blocks') visual?.flush();
  updatePreview();
  if (!valid || !currentDiagram) return;
  const snapshot = currentDiagram;
  if ($('export-format').value === 'svg') {
    try {
      if (await download(new Blob([snapshot.svg], { type: 'image/svg+xml;charset=utf-8' }), '.svg')) toast('SVG saved');
    } catch { toast('Could not save the SVG. Try another location.'); }
    return;
  }
  try {
    const url = URL.createObjectURL(new Blob([snapshot.svg], { type: 'image/svg+xml;charset=utf-8' }));
    const img = new Image();
    try { img.src = url; await img.decode(); }
    finally { URL.revokeObjectURL(url); }
    const output = document.createElement('canvas');
    const scale = Math.min(2, 8192 / Math.max(snapshot.width, snapshot.height), Math.sqrt(24_000_000 / (snapshot.width * snapshot.height)));
    output.width = Math.max(1, Math.ceil(snapshot.width * scale));
    output.height = Math.max(1, Math.ceil(snapshot.height * scale));
    const painter = output.getContext('2d');
    painter.fillStyle = '#fff';
    painter.fillRect(0, 0, output.width, output.height);
    painter.drawImage(img, 0, 0, output.width, output.height);
    const blob = await new Promise(resolve => output.toBlob(resolve, 'image/png'));
    if (!blob) throw new Error('Could not create the image.');
    if (await download(blob, '.png')) toast('PNG saved');
  } catch { toast('PNG export failed. Try SVG, which preserves the full diagram.'); }
}

examples.forEach((example, index) => {
  const button = document.createElement('button');
  button.className = 'example-button';
  button.dataset.example = example.id;
  button.title = example.description;
  const number = document.createElement('span');
  number.className = 'example-number';
  number.textContent = String(index + 1).padStart(2, '0');
  button.append(number, document.createTextNode(example.title));
  button.addEventListener('click', () => replaceDocument(example));
  $('examples').append(button);
});

for (const [symbol, meaning] of [[':=', 'Assignment'], ['→', 'Pointer field'], ['∅', 'Null pointer'], ['≠', 'Not equal'], ['≤', 'Less than or equal'], ['≥', 'Greater than or equal'], ['∧', 'Logical and'], ['∨', 'Logical or'], ['¬', 'Logical not'], ['∀', 'For all'], ['∈', 'Element of'], ['∞', 'Infinity'], ['π', 'Parent / pi']]) {
  const button = document.createElement('button');
  button.textContent = symbol;
  button.title = meaning;
  button.setAttribute('aria-label', `Insert ${meaning.toLowerCase()} (${symbol})`);
  button.addEventListener('pointerdown', event => event.preventDefault());
  button.addEventListener('click', () => {
    if (editorMode === 'blocks') { if (!visual?.insertSymbol(symbol)) toast('Select a block or click its text field first.'); }
    else editText(source.selectionStart, source.selectionEnd, symbol);
  });
  $('symbols').append(button);
}

document.querySelectorAll('[data-insert]').forEach(button => button.addEventListener('click', () => insertConstruct(button.dataset.insert)));
document.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click', () => $(button.dataset.close).close()));
$('open-guide').addEventListener('click', () => { closeNavigation(); $('guide-dialog').showModal(); });
$('toggle-nav').addEventListener('click', () => {
  if (document.body.classList.contains('nav-open')) closeNavigation();
  else {
    document.body.classList.add('nav-open');
    $('nav-backdrop').hidden = false;
    $('toggle-nav').setAttribute('aria-expanded', 'true');
    $('new-document').focus();
  }
});
$('nav-backdrop').addEventListener('click', closeNavigation);
$('new-document').addEventListener('click', () => replaceDocument(blank));
$('confirm-replace').addEventListener('click', () => { $('replace-dialog').close(); if (pendingReplacement) loadDocument(pendingReplacement); pendingReplacement = null; });
$('save-before-replace').addEventListener('click', saveSource);
$('save-source').addEventListener('click', saveSource);
$('export-diagram').addEventListener('click', exportDiagram);
$('print-diagram').addEventListener('click', async () => {
  if (editorMode === 'blocks') visual?.flush();
  updatePreview();
  if (!valid) return;
  try { window.print(); }
  catch { toast('Could not open the print dialog.'); }
});
$('import-source').addEventListener('click', () => $('file-input').click());
$('file-input').addEventListener('change', async event => {
  const file = event.target.files[0];
  event.target.value = '';
  if (!file) return;
  if (file.size > 400_000) { toast('Please open a source file smaller than 400 KB.'); return; }
  try { importSource(file.name, await file.text()); }
  catch { toast('Could not read this source file.'); }
});

function importSource(name, text) {
  try {
    const filename = name.replace(/\.[^.]+$/, '').replace(/[-_]/g, ' ');
    let next = { title: filename.slice(0, 100), source: text };
    if (/\.json$/i.test(name)) {
      const data = JSON.parse(text);
      if (typeof data.source !== 'string') throw new Error('Missing source text.');
      next = { title: typeof data.title === 'string' ? data.title.slice(0, 100) : filename, source: data.source };
    }
    if (next.source.length > 100_000) throw new Error('Too large.');
    replaceDocument(next);
  } catch { toast('Could not open this file. Use a text source file or JSON with a source field.'); }
}

source.addEventListener('input', documentChanged);
source.addEventListener('click', updateCursor);
source.addEventListener('keyup', updateCursor);
source.addEventListener('select', updateCursor);
source.addEventListener('scroll', () => { $('line-numbers').scrollTop = source.scrollTop; });
source.addEventListener('keydown', event => {
  if (event.key === 'Tab') {
    event.preventDefault();
    const start = source.selectionStart, end = source.selectionEnd;
    const blockStart = source.value.lastIndexOf('\n', start - 1) + 1;
    if (start === end && !event.shiftKey) { editText(start, end, '  '); return; }
    const selected = source.value.slice(blockStart, end);
    const replacement = selected.split('\n').map(line => event.shiftKey ? line.replace(/^ {1,2}/, '') : '  ' + line).join('\n');
    editText(blockStart, end, replacement);
    source.setSelectionRange(blockStart, blockStart + replacement.length);
  } else if (event.key === 'Enter' && !event.ctrlKey && !event.metaKey && !event.isComposing) {
    event.preventDefault();
    const before = source.value.slice(0, source.selectionStart).split('\n').at(-1);
    let indent = before.match(/^\s*/)[0];
    if (/^\s*(?:if\b|else\b|elif\b|while\b|for\b|foreach\b|select\b|case\b|otherwise\b)/.test(before) || /^\S.*\(.*\)/.test(before)) indent += '  ';
    editText(source.selectionStart, source.selectionEnd, '\n' + indent);
  }
});

title.addEventListener('input', () => { documentState.modified = true; updateDocumentLabel(); persist(); updatePreview(); });
stage.addEventListener('click', event => {
  const row = event.target.closest('[data-line]');
  if (!row) return;
  const lineNumber = Number(row.dataset.line);
  if (editorMode === 'blocks') { visual?.selectLine(lineNumber); return; }
  const lines = source.value.split('\n');
  const start = lines.slice(0, lineNumber - 1).reduce((sum, line) => sum + line.length + 1, 0);
  source.focus();
  source.setSelectionRange(start, start + lines[lineNumber - 1].length);
  source.scrollTop = Math.max(0, (lineNumber - 4) * 27);
  updateCursor();
});

function changeZoom(delta) { fitMode = false; zoom = Math.min(2, Math.max(.1, Math.round((zoom + delta) * 100) / 100)); applyZoom(); }
$('zoom-in').addEventListener('click', () => changeZoom(.1));
$('zoom-out').addEventListener('click', () => changeZoom(-.1));
$('zoom-reset').addEventListener('click', () => { fitMode = false; zoom = 1; applyZoom(); });
$('zoom-fit').addEventListener('click', () => { fitMode = true; applyZoom(); });
new ResizeObserver(() => { if (fitMode) applyZoom(); if (editorMode === 'blocks') visual?.resize(); }).observe($('preview-viewport'));
document.addEventListener('keydown', event => {
  if (event.key === 'Escape' && document.body.classList.contains('nav-open')) { closeNavigation(); $('toggle-nav').focus(); }
  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 's') { event.preventDefault(); saveSource(); }
});
window.addEventListener('beforeprint', updatePreview);
function saveBeforeUpdate() {
  // Commit an actively edited Blockly field before serializing its workspace.
  if (document.activeElement?.classList.contains('blocklyHtmlInput')) document.activeElement.blur();
  if (editorMode === 'blocks') visual?.flush();
  persist();
  return storageAvailable;
}
window.addEventListener('structogram-before-update', event => {
  if (!saveBeforeUpdate()) event.preventDefault();
});
window.addEventListener('pagehide', saveBeforeUpdate);

source.value = documentState.source;
title.value = documentState.title;
const initialMode = documentState.editorMode === 'text' ? 'text' : 'blocks';
try {
  visual = createBlockEditor($('block-workspace'), result => {
    if (editorMode !== 'blocks') return;
    documentState.blockWorkspace = result.state;
    documentState.blockSource = source.value;
    if (result.error) { documentState.modified = true; persist(); updatePreview(); return; }
    if (result.changed) {
      source.value = result.source;
      lastBlockSource = result.source;
      documentState.blockSource = result.source;
      documentChanged(true);
    } else persist();
  });
} catch (error) { toast(error.message); }
$('mode-blocks').addEventListener('click', () => setEditorMode('blocks'));
$('mode-text').addEventListener('click', () => setEditorMode('text'));
$('undo-blocks').addEventListener('click', () => undoEditing(false));
$('redo-blocks').addEventListener('click', () => undoEditing(true));
for (const mode of ['blocks', 'text']) $('mode-' + mode).addEventListener('keydown', event => {
  if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
    event.preventDefault();
    const next = mode === 'blocks' ? 'text' : 'blocks';
    if (setEditorMode(next)) $('mode-' + next).focus();
  }
});
if (!setEditorMode(visual ? initialMode : 'text')) setEditorMode('text');
updateLines();
updateDocumentLabel();
updatePreview();
if (!storageAvailable) $('save-status').textContent = 'Use Save source to keep your work';

initWorkspaceLayout(() => {
  if (editorMode === 'blocks') visual?.resize();
  if (fitMode) applyZoom();
});

};
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', start, { once: true });
} else {
  start();
}
})();
